  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_applicant`(`applicant_id` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_type`(`type_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_dept`(`dept_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '项目实例主表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_project
-- ----------------------------

-- ----------------------------
-- Table structure for review_project_modify_log
-- ----------------------------
DROP TABLE IF EXISTS `review_project_modify_log`;
CREATE TABLE `review_project_modify_log`  (
  `id` bigint NOT NULL COMMENT '日志ID（雪花ID）',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `modified_by` bigint NOT NULL COMMENT '修改人用户ID（实际发起修改的人，可能是管理员代改）',
  `old_form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '修改前申请表单数据',
  `new_form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '修改后申请表单数据',
  `modify_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '修改原因（可选）',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project`(`project_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_modified_by`(`modified_by` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '申请表单修改痕迹日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_project_modify_log
-- ----------------------------

-- ----------------------------
-- Table structure for review_project_stage
-- ----------------------------
DROP TABLE IF EXISTS `review_project_stage`;
CREATE TABLE `review_project_stage`  (
  `id` bigint NOT NULL COMMENT '阶段ID（雪花ID）',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `stage_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '阶段类型（KICKOFF/EXECUTION/ACCEPTANCE）',
  `stage_order` int NOT NULL COMMENT '阶段序号（来自管理流程模板 stage_order）',
  `original_stage_order` int NOT NULL COMMENT '原始阶段序号（模板中的序号）',
  `execution_sequence` int NOT NULL DEFAULT 1 COMMENT '执行序号（同一原始阶段的第N次执行）',
  `stage_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '阶段名称（来自快照）',
  `planned_days` int NULL DEFAULT NULL COMMENT '计划天数（来自快照，暂未被模板模块支持，预留）',
  `start_date` date NULL DEFAULT NULL COMMENT '实际开始日期（阶段激活时设置）',
  `deadline` date NULL DEFAULT NULL COMMENT '计划完成日期（start_date + planned_days，planned_days 不为空时计算）',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '阶段状态（PENDING/IN_PROGRESS/SUBMITTED/COMPLETED/REJECTED）',
  `is_overdue` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否超时（0否1是，定时任务维护）',
  `reject_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '驳回原因',
  `stage_form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '申请人提交的阶段成果表单数据（重做时直接覆盖）',
  `submitter_id` bigint NULL DEFAULT NULL COMMENT '阶段提交人ID（STAGE_SUBMISSION任务转办时更新）',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_project_stage_order`(`project_id` ASC, `stage_order` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_project`(`project_id` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_stage_type`(`stage_type` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '管理阶段实例表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_project_stage
-- ----------------------------

-- ----------------------------
-- Table structure for review_project_stage_history
-- ----------------------------
DROP TABLE IF EXISTS `review_project_stage_history`;
CREATE TABLE `review_project_stage_history`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `stage_id` bigint NOT NULL COMMENT '阶段ID',
  `project_id` bigint NULL DEFAULT NULL COMMENT '项目ID',
  `stage_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阶段类型',
  `stage_order` int NULL DEFAULT NULL COMMENT '阶段序号',
  `stage_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '阶段名称',
  `old_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '原状态',
  `new_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '新状态',
  `start_date` date NULL DEFAULT NULL COMMENT '开始日期',
  `deadline` date NULL DEFAULT NULL COMMENT '截止日期',
  `stage_form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '阶段成果表单数据',
  `change_time` datetime NOT NULL COMMENT '变更时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_stage_id`(`stage_id` ASC) USING BTREE,
  INDEX `idx_project_stage`(`project_id` ASC, `stage_order` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 828024181370290193 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '阶段状态历史表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_project_stage_history
-- ----------------------------

-- ----------------------------
-- Table structure for review_project_type
-- ----------------------------
DROP TABLE IF EXISTS `review_project_type`;
CREATE TABLE `review_project_type`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '类型ID',
  `type_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型名称',
  `type_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '类型编码（唯一，创建后不可修改）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序',
  `status` tinyint(1) UNSIGNED NOT NULL DEFAULT 0 COMMENT '状态（0：草稿；1：已启用；2：已禁用）',
  `dept_id` bigint NOT NULL DEFAULT 1 COMMENT '所属部门ID（TYPE_ADMIN数据权限范围）',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_code`(`type_code` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_dept_id`(`dept_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 828344394989080742 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '项目类型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_project_type
-- ----------------------------

-- ----------------------------
-- Table structure for review_task
-- ----------------------------
DROP TABLE IF EXISTS `review_task`;
CREATE TABLE `review_task`  (
  `id` bigint NOT NULL COMMENT '任务ID（雪花ID）',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `task_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '任务类型（AUDIT/REVIEW/DECISION/MANAGEMENT/ACCEPTANCE）',
  `node_sequence` int NULL DEFAULT NULL COMMENT '节点序号（轮次序号或阶段序号）',
  `assignee_id` bigint NOT NULL COMMENT '被分配人用户ID',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'PENDING' COMMENT '任务状态（PENDING/SAVED/COMPLETED/TRANSFERRED/CANCELLED）',
  `decision` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '决策结果（PASS/REJECT/UNQUALIFIED/WITHDRAW）',
  `score` decimal(6, 2) NULL DEFAULT NULL COMMENT '评分（SCORE_PASS 模式时填写）',
  `form_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '任务表单填写数据',
  `reject_back_to_stage_order` int NULL DEFAULT NULL COMMENT '验收任务 REJECT 时指定回退到的阶段序号',
  `transfer_count` int NOT NULL DEFAULT 0 COMMENT '转办次数（上限 MAX_TRANSFER_COUNT=3）',
  `transfer_remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '转办说明（转办时填写，留存最后一次转办原因）',
  `assign_time` datetime NULL DEFAULT NULL COMMENT '分配时间',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_assignee`(`assignee_id` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_project_node`(`project_id` ASC, `task_type` ASC, `node_sequence` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_project`(`project_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_task_type`(`task_type` ASC, `status` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '任务实例表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_task
-- ----------------------------

-- ----------------------------
-- Table structure for review_type_approval_config
-- ----------------------------
DROP TABLE IF EXISTS `review_type_approval_config`;
CREATE TABLE `review_type_approval_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type_id` bigint NOT NULL COMMENT '项目类型ID',
  `node_scope` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点标识（如 AUDIT_1、REVIEW_1、DECISION_1、ACCEPTANCE）',
  `required_reviewer_count` int NULL DEFAULT NULL COMMENT '所需审批人数（用于校验人员范围是否满足要求）',
  `approval_mode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批模式（VOTE_ALL_PASS/VOTE_MAJORITY_PASS/VOTE_ONE_PASS/SCORE_PASS）',
  `majority_ratio` decimal(4, 2) NULL DEFAULT 0.67 COMMENT '多数通过比例（0~1），仅 VOTE_MAJORITY_PASS 时有效，默认0.67',
  `pass_threshold` decimal(6, 2) NULL DEFAULT NULL COMMENT '评分通过阈值，SCORE_PASS 时必填',
  `good_threshold` decimal(6, 2) NULL DEFAULT NULL COMMENT '良好阈值（可选）',
  `excellent_threshold` decimal(6, 2) NULL DEFAULT NULL COMMENT '优秀阈值（可选）',
  `score_calc_method` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评分计算方式（WEIGHTED_AVG/AVG/MIN），SCORE_PASS 时必填',
  `weight_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评审人权重模式（EQUAL/PRESET），SCORE_PASS 时必填',
  `score_table_weights` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL COMMENT '多个SCORE_TABLE字段间的权重，格式：{\"fieldCode\":0.4}，仅一个SCORE_TABLE时为NULL',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_node`(`type_id` ASC, `node_scope` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_type`(`type_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 828014438786433102 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '类型审批规则配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_type_approval_config
-- ----------------------------

-- ----------------------------
-- Table structure for review_type_form_mapping
-- ----------------------------
DROP TABLE IF EXISTS `review_type_form_mapping`;
CREATE TABLE `review_type_form_mapping`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type_id` bigint NOT NULL COMMENT '项目类型ID',
  `mapping_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '映射类型（REVIEW=评审流程,MANAGE=管理流程）',
  `node_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点类型（APPLICATION=申请,AUDIT=审核,REVIEW=评审,DECISION=决策,STAGE=管理阶段）',
  `node_sequence` int NULL DEFAULT NULL COMMENT '节点序号（APPLICATION节点为NULL，其他节点从1开始与流程轮次/阶段序号对应）',
  `form_template_id` bigint NOT NULL COMMENT '表单模板ID（逻辑外键）',
  `form_template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表单模板名称（冗余）',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_node`(`type_id` ASC, `mapping_type` ASC, `node_type` ASC, `node_sequence` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_type`(`type_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_form_template`(`form_template_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_mapping_type`(`mapping_type` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 828014438824181850 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '类型表单映射表' ROW_FORMAT = Dynamic;

