CREATE TABLE `review_type_personnel_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type_id` bigint NOT NULL COMMENT '项目类型ID',
  `node_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '节点类型（APPLICATION/AUDIT/REVIEW/DECISION/STAGE）',
