  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_node_scope`(`type_id` ASC, `node_type` ASC, `node_sequence` ASC, `scope_type` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_type`(`type_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE,
  INDEX `idx_node_type`(`node_type` ASC, `node_sequence` ASC, `deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 828014438794821715 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '类型人员范围配置表' ROW_FORMAT = Dynamic;

