-- ----------------------------
-- Table structure for review_type_reviewer_weight
-- ----------------------------
DROP TABLE IF EXISTS `review_type_reviewer_weight`;
CREATE TABLE `review_type_reviewer_weight`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `type_id` bigint NOT NULL COMMENT '项目类型ID',
  `node_scope` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点标识（与approval_config.node_scope对应）',
  `user_id` bigint NOT NULL COMMENT '评审人用户ID（必须在对应角色的USER人员范围内）',
  `user_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '评审人姓名（冗余）',
  `weight` decimal(5, 4) NOT NULL COMMENT '权重值（0~1，同一节点所有人权重之和须=1.0）',
  `create_user` bigint NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_user` bigint NULL DEFAULT NULL COMMENT '修改人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '修改时间',
  `deleted` bigint NOT NULL DEFAULT 0 COMMENT '是否已删除（0：否；id：是）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_type_node_user`(`type_id` ASC, `node_scope` ASC, `user_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_type_node`(`type_id` ASC, `node_scope` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_user`(`user_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_create_user`(`create_user` ASC) USING BTREE,
  INDEX `idx_update_user`(`update_user` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '类型评审人权重配置表（PRESET模式专用）' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of review_type_reviewer_weight
