  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_source_open_id`(`source` ASC, `open_id` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_deleted`(`deleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户社会化关联表' ROW_FORMAT = Dynamic;

